// Fails when a README's install-flow diagram is missing, malformed, or no
// longer referenced.
//
// The diagrams are committed as static SVG (assets/install-flow.{en,zh}.svg)
// generated by tools/make-install-flow-svg.py. They are deliberately NOT
// Mermaid: GitHub renders Mermaid inside an iframe served by
// viewscreen.githubusercontent.com, and when that host is unreachable (proxy
// rules, restricted networks) readers only see "Unable to render rich
// display". A static SVG renders everywhere and looks identical in GitHub's
// light and dark themes.
import fs from 'node:fs'

const PAIRS = [
  ['README.md', 'assets/install-flow.en.svg'],
  ['README.zh.md', 'assets/install-flow.zh.svg'],
]

let failed = false

for (const [readme, asset] of PAIRS) {
  const src = fs.readFileSync(readme, 'utf8')
  if (!src.includes(asset)) {
    console.error(`FAIL ${readme} does not reference ${asset}`)
    failed = true
  }
  if (!fs.existsSync(asset)) {
    console.error(`FAIL missing diagram asset ${asset}`)
    failed = true
    continue
  }
  const svg = fs.readFileSync(asset, 'utf8').trim()
  if (!svg.startsWith('<svg') || !svg.endsWith('</svg>')) {
    console.error(`FAIL ${asset} is not a self-contained SVG document`)
    failed = true
  }
  if (!svg.includes('<title')) {
    console.error(`FAIL ${asset} has no <title> (accessibility)`)
    failed = true
  }
}

// Mermaid blocks must not creep back into the READMEs.
for (const readme of ['README.md', 'README.zh.md']) {
  if (/```mermaid/.test(fs.readFileSync(readme, 'utf8'))) {
    console.error(`FAIL ${readme} still contains a mermaid block — use the static SVG diagram`)
    failed = true
  }
}

// The diagrams print the plugin version; keep them in step with package.json.
const version = JSON.parse(fs.readFileSync('package.json', 'utf8')).version
for (const [, asset] of PAIRS) {
  if (!fs.existsSync(asset)) continue
  if (!fs.readFileSync(asset, 'utf8').includes(version)) {
    console.error(`FAIL ${asset} does not show the current version ${version} — regenerate it`)
    failed = true
  }
}

if (failed) process.exit(1)
console.log('diagram assets ok')
